// --------------------------------------
// 1) Noise/FBM
// --------------------------------------
float hash21(vec2 p) {
    p = fract(p * 2345.6789);
    p += dot(p, p + 34.123);
    return fract(p.x * p.y);
}

float noise2D(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    float a = hash21(i + vec2(0.0, 0.0));
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    vec2 u = f*f*(3.0-2.0*f);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float sum = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    for(int i=0; i<5; i++){
        sum += noise2D(p*freq) * amp;
        freq *= 2.0;
        amp *= 0.5;
    }
    return sum;
}

// The height map
float getHeight(vec2 xz) {
    // Scale as you like
    return fbm(xz * 1.2);
}

float getHeightTimeBased(vec2 xz) {
    // Add time-based offset so terrain scrolls "under" the camera
    vec2 scroll = vec2(iTime * 0.1, 0.0);
    return fbm(xz*1.5 + scroll);
}

// --------------------------------------
// 2) Raymarch routine
// --------------------------------------
float castRay(in vec3 ro, in vec3 rd) {
    float t = 0.0;
    float stepSize = 0.01; // smaller => more detail but more steps

    for(int i = 0; i < 512; i++) {
        vec3 pos = ro + rd * t;
        float terrainH = getHeight(pos.xz);
        // If the ray is below the terrain surface
        if(pos.y < terrainH) {
            return t;
        }
        t += stepSize;
        // Possibly break if we go too far
        if(t>10.0) break;
    }
    return -1.0; // no intersection
}

// --------------------------------------
// 3) Normal & shading
// --------------------------------------
vec3 computeNormal(vec3 pos) {
    float eps = 0.002;
    float h   = getHeight(pos.xz);
    float hx  = getHeight(pos.xz + vec2(eps, 0.0));
    float hy  = getHeight(pos.xz + vec2(0.0, eps));
    float dx  = hx - h;
    float dy  = hy - h;

    vec3 normal = normalize(vec3(-dx, 1.0, -dy));
    return normal;
}

vec3 terrainColor(float h) {
    if(h < 0.3) {
        // Water
        return mix(vec3(0.0, 0.2, 0.7), vec3(0.2, 0.7, 1.0), smoothstep(0.0, 0.3, h));
    }
    else if(h < 0.6) {
        // Green to brown
        float factor = smoothstep(0.3, 0.6, h);
        vec3 green = vec3(0.1, 0.6, 0.1);
        vec3 brown = vec3(0.4, 0.2, 0.05);
        return mix(green, brown, factor);
    }
    else {
        // Brown to snow
        float factor = smoothstep(0.6, 0.9, h);
        vec3 brown = vec3(0.4, 0.2, 0.05);
        vec3 snow  = vec3(0.9, 0.9, 1.0);
        return mix(brown, snow, factor);
    }
}

vec3 shadeTerrain(vec3 pos) {
    float h = getHeight(pos.xz);
    vec3 baseColor = terrainColor(h);

    // Normal from the height field
    vec3 normal = computeNormal(pos);

    // Directional light
    vec3 lightDir = normalize(vec3(0.5, 1.0, 0.2));
    float lambert = max(dot(normal, lightDir), 0.0);

    // Basic Lambert
    float ambient = 0.3;
    vec3 color = baseColor * lambert * (1.0 - ambient) + baseColor * ambient;

    // Optionally add a bit of spec
    vec3 viewDir = normalize(-pos); // if ro ~ (0,0,-something), approximate
    vec3 halfDir = normalize(lightDir + viewDir);
    float spec = pow(max(dot(normal, halfDir), 0.0), 16.0);
    color += vec3(1.0) * spec * 0.2; 

    return color;
}

// --------------------------------------
// Main entry
// --------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord) { 
    // Camera setup
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Animate the camera position using iTime
    // For example, move along Z from -5.0 to +something:
    float speed = 0.2;   // how fast we fly
    float camZ  = -5.0 + iTime * speed;  // or just iTime if you want unlimited flight

    // Keep the same X, but maybe give it a gentle bounce in Y
    float camY = 2.0 + 0.5 * sin(iTime * 0.3);

    // Set the camera position
    vec3 ro = vec3(0.0, camY, camZ);

    // We want to look "forward" (down +Z), or you can aim at a fixed point
    // e.g. aim 5 units in front of the camera on the Z axis:
    // Or aim at the origin if your terrain’s interesting there:
    vec3 target = vec3(0.0, 0.0, camZ + 1.0);

    // Build forward, right, up:
    vec3 forward = normalize(target - ro);
    vec3 right   = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up      = cross(right, forward);

    float fov = 1.2; // Tweak for wide or narrow view
    vec3 rd = normalize(uv.x*right + uv.y*up + fov*forward);
    // Raymarch
    float t = castRay(ro, rd);
    if(t < 0.0) {
        // Nothing hit => sky color
        fragColor = vec4(0.7, 0.8, 1.0, 1.0); // or do fancy sky
        return;
    }

    // Intersection
    vec3 pos = ro + rd * t;
    vec3 color = shadeTerrain(pos);

    fragColor = vec4(color, 1.0);
}
